<?php
declare(strict_types=1);
require dirname(__DIR__).'/app.php';
date_default_timezone_set('America/Guayaquil');
// This is an admin-only prototype. Allow loopback testing; otherwise require
// HTTPS and authentication enforced by the web server (cPanel Directory Privacy).
$localRequest = in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1', '::1'], true)
    && in_array(strtolower(parse_url('http://'.($_SERVER['HTTP_HOST'] ?? ''), PHP_URL_HOST) ?? ''), ['localhost','127.0.0.1','[::1]'], true);
$httpsRequest = !empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off';
$serverUser = $_SERVER['REMOTE_USER'] ?? $_SERVER['REDIRECT_REMOTE_USER'] ?? '';
if (!$localRequest && (!$httpsRequest || !is_string($serverUser) || $serverUser === '')) {
    http_response_code(403);
    exit('Panel privado: configura HTTPS y la privacidad del directorio en el hosting antes de acceder.');
}

// Reject unexpected paths when the built-in server falls back to index.php.
$requestPath=parse_url($_SERVER['REQUEST_URI']??'/', PHP_URL_PATH);
if (!is_string($requestPath) || (!str_ends_with($requestPath, '/') && basename($requestPath)!=='index.php') || !empty($_SERVER['PATH_INFO'])) { http_response_code(404); exit('No encontrado.'); }
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: no-referrer');
header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'");
if (isset($_GET['image'])) handle_image();
header('Cache-Control: no-store');
session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off')]);
session_start();
$_SESSION['csrf'] ??= bin2hex(random_bytes(32));
if ($_SERVER['REQUEST_METHOD']==='POST') process_post();
$flash=$_SESSION['flash']??null; unset($_SESSION['flash']);
try { $data=db(static fn($d)=>$d); } catch(Throwable $e) { error_log((string)$e); http_response_code(500); exit('No se pudo conectar con MySQL o leer la base de datos. Importa database/sorteos_studio.sql en la base seleccionada, revisa config.php y habilita pdo_mysql.'); }
$nav=['sorteos'=>['Sorteos','ticket'],'participantes'=>['Participantes','users'],'ganadores'=>['Ganadores','trophy'],'ingresos'=>['Ingresos','wallet']];
$page=q('page','sorteos'); if (!isset($nav[$page])) $page='sorteos';
