$counts=['todos'=>count($all),'activo'=>0,'borrador'=>0,'finalizado'=>0];
$summary=['count'=>0,'paid'=>0,'pending'=>0,'income'=>0,'pending_income'=>0]; $metrics=[];
foreach($all as $r) { $counts[$r['status']]++; $metrics[$r['id']]=stats($data,$r); foreach($summary as $k=>$v) $summary[$k]+=$metrics[$r['id']][$k]; }
$filter=q('status','todos'); if (!isset($counts[$filter])) $filter='todos';
$selected=$page==='participantes'?($data['raffles'][q('id')]??null):null;
