];
function ico(string $name): string { global $icons; return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($icons[$name]??'').'</svg>'; }
function chip(string $s): string { return '<span class="status '.$s.'"><i></i>'.h(STATES[$s]??PAYMENTS[$s]??$s).'</span>'; }
function csrf(): string { return '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">'; }
function action_button(string $action,string $id,string $label,string $icon,string $confirm='',string $pid=''): string {
    return '<form method="post" class="inline-form"'.($confirm!==''?' data-confirm="'.h($confirm).'"':'').'>'.csrf().'<input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="raffle_id" value="'.h($id).'"><input type="hidden" name="participant_id" value="'.h($pid).'"><button class="icon-btn" type="submit" aria-label="'.h($label).'" title="'.h($label).'">'.ico($icon).'</button></form>';
}
function json_attr(array $r): string { return h(json_encode($r, JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)); }
function thumb(array $r): string { $p=array_values(array_filter($r['photos']))[0]??null; return '<span class="thumb">'.($p?'<img src="index.php?image='.h($p).'" alt="" loading="lazy">':ico($r['type']==='dinero'?'cash':'box')).'</span>'; }
function searchbox(string $placeholder): string { return '<label class="searchbox">'.ico('search').'<input id="searchInput" type="search" placeholder="'.h($placeholder).'" aria-label="'.h($placeholder).'"></label>'; }
function metric(string $label,string $value,string $icon,string $sub=''): void { echo '<div class="metric"><span class="metric-icon">'.ico($icon).'</span><span class="metric-label">'.h($label).'</span><strong>'.h($value).'</strong><small>'.h($sub).'</small></div>'; }
function empty_state(string $title,string $detail,string $icon='ticket'): void { echo '<div class="empty"><span class="empty-icon">'.ico($icon).'</span><strong>'.h($title).'</strong><p>'.h($detail).'</p></div>'; }
?>
